content.text:
{
  "params": [
    {
      "description": "Legal name of the end customer company buying through Caravela",
      "name": "end_customer_company",
      "newName": "end_customer_company",
      "type": "string"
    },
    {
      "description": "End customer company website",
      "name": "company_website",
      "newName": "company_website",
      "type": "string"
    },
    {
      "description": "End customer country",
      "name": "country",
      "newName": "country",
      "type": "enum"
    },
    {
      "description": "End customer city",
      "name": "city",
      "newName": "city",
      "type": "string"
    },
    {
      "description": "Full name of the contact at the end customer",
      "name": "contact_full_name",
      "newName": "contact_full_name",
      "type": "string"
    },
    {
      "description": "Email address of the end customer contact",
      "name": "contact_email",
      "newName": "contact_email",
      "type": "email"
    },
    {
      "description": "Phone number of the end customer contact",
      "name": "contact_phone",
      "newName": "contact_phone",
      "type": "phone"
    },
    {
      "description": "Caravela / Tidewater Cloud product for the opportunity",
      "name": "product",
      "newName": "product",
      "type": "enum"
    },
    {
      "description": "Number of seats for the opportunity",
      "name": "seats",
      "newName": "seats",
      "type": "number"
    },
    {
      "description": "Expected close date in DD/MM/YYYY format, a date in the future",
      "name": "expected_close_date",
      "newName": "expected_close_date",
      "type": "date"
    },
    {
      "description": "Referral partner or agent name, if applicable",
      "name": "referral_partner",
      "newName": "referral_partner",
      "type": "string"
    },
    {
      "description": "Additional notes about the opportunity for Caravela",
      "name": "notes",
      "newName": "notes",
      "type": "string"
    }
  ],
  "steps": [
    {
      "id": "s1",
      "intent": "Open the Register a deal form in the Caravela Partner Hub"
    },
    {
      "id": "s2",
      "intent": "Enter the end customer company in the End customer company field"
    },
    {
      "id": "s3",
      "intent": "Enter the company website in the Company website field"
    },
    {
      "id": "s4",
      "intent": "Select the country from the Country dropdown"
    },
    {
      "id": "s5",
      "intent": "Enter the city in the City field"
    },
    {
      "id": "s6",
      "intent": "Enter the contact name in the Contact full name field"
    },
    {
      "id": "s7",
      "intent": "Enter the contact email in the Contact email field"
    },
    {
      "id": "s8",
      "intent": "Enter the contact phone in the Contact phone field"
    },
    {
      "id": "s9",
      "intent": "Select the product from the Product dropdown"
    },
    {
      "id": "s10",
      "intent": "Enter the number of seats in the Seats field"
    },
    {
      "id": "s11",
      "intent": "Enter the expected close date in the Expected close date field"
    },
    {
      "id": "s12",
      "intent": "Enter the referral partner name in the Referral partner field"
    },
    {
      "id": "s13",
      "intent": "Enter additional details in the Notes field under Additional information"
    },
    {
      "id": "s14",
      "intent": "Check the The end customer agreed to be contacted by Caravela checkbox"
    },
    {
      "id": "s15",
      "intent": "Click Submit registration to submit the deal registration"
    }
  ],
  "success": {
    "description": "A Registration received confirmation page is shown with a green checkmark, Status Pending review, Submitted date/time, and a Registration details summary",
    "idName": "registration_id",
    "idRegex": "NW-REG-\\d{5}",
    "textPattern": "Registration received"
  },
  "title": "Register a deal"
}
